import{_ as a,c as e,o,a0 as i}from"./chunks/framework.DKRgXLPU.js";const s=JSON.parse('{"title":"Building Pre-Shot Routines","description":"Develop a consistent pre-shot routine that anchors your focus, manages pressure, and creates the conditions for peak performance in pétanque.","frontmatter":{"title":"Building Pre-Shot Routines","description":"Develop a consistent pre-shot routine that anchors your focus, manages pressure, and creates the conditions for peak performance in pétanque."},"headers":[],"relativePath":"pt/blog/pre-shot-routines.md","filePath":"pt/blog/pre-shot-routines.md"}');const r=a({name:"pt/blog/pre-shot-routines.md"},[["render",function(a,s,r,t,n,l){return o(),e("div",null,[...s[0]||(s[0]=[i('<h1 id="criando-rotinas-pre-filmagem" tabindex="-1">Criando rotinas pré-filmagem <a class="header-anchor" href="#criando-rotinas-pre-filmagem" aria-label="Permalink to &quot;Criando rotinas pré-filmagem&quot;">​</a></h1><p>A diferença entre um bom arremesso e um arremesso excelente muitas vezes acontece antes mesmo da bola sair da sua mão. Uma rotina pré-arremesso bem planejada é a sua âncora na tempestade da competição — uma sequência confiável que prepara sua mente e seu corpo para um desempenho ideal.</p><h2 id="por-que-as-rotinas-pre-filmagem-sao-importantes" tabindex="-1">Por que as rotinas pré-filmagem são importantes <a class="header-anchor" href="#por-que-as-rotinas-pre-filmagem-sao-importantes" aria-label="Permalink to &quot;Por que as rotinas pré-filmagem são importantes&quot;">​</a></h2><p>Atletas de elite em todos os esportes utilizam rotinas pré-lançamento. Na petanca, onde cada lançamento é único e a pressão pode aumentar entre os lançamentos, as rotinas servem a múltiplos propósitos:</p><ul><li><strong>Consistência</strong>: A mesma preparação leva a uma execução mais consistente.</li><li><strong>Concentração</strong>: Dá à sua mente uma tarefa construtiva em vez de se preocupar.</li><li><strong>Transição</strong>: Ajuda você a passar do pensamento à ação.</li><li><strong>Gestão da pressão</strong>: Ações familiares acalmam o sistema nervoso.</li><li><strong>Reiniciar</strong>: Apaga a gravação anterior da sua mente.</li></ul><h2 id="anatomia-de-uma-rotina-eficaz" tabindex="-1">Anatomia de uma rotina eficaz <a class="header-anchor" href="#anatomia-de-uma-rotina-eficaz" aria-label="Permalink to &quot;Anatomia de uma rotina eficaz&quot;">​</a></h2><p>Uma boa rotina pré-filmagem tem três fases:</p><h3 id="fase-1-avaliacao-5-10-segundos" tabindex="-1">Fase 1: Avaliação (5-10 segundos) <a class="header-anchor" href="#fase-1-avaliacao-5-10-segundos" aria-label="Permalink to &quot;Fase 1: Avaliação (5-10 segundos)&quot;">​</a></h3><ul><li>Leia o terreno</li><li>Visualize o resultado desejado</li><li>Escolha o seu tipo de arremesso</li><li>Comprometa-se com a decisão.</li></ul><h3 id="fase-2-preparacao-5-10-segundos" tabindex="-1">Fase 2: Preparação (5-10 segundos) <a class="header-anchor" href="#fase-2-preparacao-5-10-segundos" aria-label="Permalink to &quot;Fase 2: Preparação (5-10 segundos)&quot;">​</a></h3><ul><li>Assuma sua posição.</li><li>Encontre seu ponto de apoio</li><li>Acalme sua respiração.</li><li>Sinta o peso da bola.</li></ul><h3 id="fase-3-execucao-3-5-segundos" tabindex="-1">Fase 3: Execução (3-5 segundos) <a class="header-anchor" href="#fase-3-execucao-3-5-segundos" aria-label="Permalink to &quot;Fase 3: Execução (3-5 segundos)&quot;">​</a></h3><ul><li>Foco final no alvo</li><li>Confie no seu corpo.</li><li>Liberte-se sem pensar.</li><li>Siga em frente naturalmente</li></ul><h2 id="construindo-sua-rotina-pessoal" tabindex="-1">Construindo sua rotina pessoal <a class="header-anchor" href="#construindo-sua-rotina-pessoal" aria-label="Permalink to &quot;Construindo sua rotina pessoal&quot;">​</a></h2><h3 id="passo-1-observe-seus-padroes-atuais" tabindex="-1">Passo 1: Observe seus padrões atuais <a class="header-anchor" href="#passo-1-observe-seus-padroes-atuais" aria-label="Permalink to &quot;Passo 1: Observe seus padrões atuais&quot;">​</a></h3><p>Antes de criar uma nova rotina, observe o que você já faz:</p><ul><li>O que você faz antes de arremessos bem-sucedidos?</li><li>O que muda quando você está sob pressão?</li><li>O que lhe parece natural?</li></ul><h3 id="etapa-2-elabore-sua-sequencia" tabindex="-1">Etapa 2: Elabore sua sequência <a class="header-anchor" href="#etapa-2-elabore-sua-sequencia" aria-label="Permalink to &quot;Etapa 2: Elabore sua sequência&quot;">​</a></h3><p>Crie uma rotina que inclua:</p><p><strong>Elementos físicos:</strong></p><ul><li>Como você aborda o círculo</li><li>Como pegar e segurar a bola</li><li>Sua postura e posicionamento.</li><li>Um padrão respiratório específico</li></ul><p><strong>Elementos mentais:</strong></p><ul><li>Uma visualização do resultado</li><li>Uma palavra ou frase de destaque</li><li>Um ponto de compromisso (o momento em que você decide &quot;este é o arremesso&quot;)</li></ul><h3 id="passo-3-mantenha-a-simplicidade" tabindex="-1">Passo 3: Mantenha a simplicidade <a class="header-anchor" href="#passo-3-mantenha-a-simplicidade" aria-label="Permalink to &quot;Passo 3: Mantenha a simplicidade&quot;">​</a></h3><p>Sua rotina deve ser:</p><ul><li><strong>Tempo suficiente</strong> para ser mantido sob pressão (15-25 segundos no total)</li><li><strong>Simples o suficiente</strong> para lembrar em momentos de estresse.</li><li><strong>Flexível o suficiente</strong> para se adaptar a diferentes situações.</li></ul><h2 id="rotinas-de-exemplo" tabindex="-1">Rotinas de exemplo <a class="header-anchor" href="#rotinas-de-exemplo" aria-label="Permalink to &quot;Rotinas de exemplo&quot;">​</a></h2><h3 id="a-rotina-do-apontador" tabindex="-1">A rotina do apontador <a class="header-anchor" href="#a-rotina-do-apontador" aria-label="Permalink to &quot;A rotina do apontador&quot;">​</a></h3><ol><li>Posicione-se atrás do círculo e avalie o terreno.</li><li>Visualize a trajetória da bola e o ponto de aterrissagem.</li><li>Entre no círculo, encontre sua posição.</li><li>Três respirações lentas enquanto sente a bola.</li><li>Olhos no alvo, disparar</li></ol><h3 id="a-rotina-do-atirador" tabindex="-1">A rotina do atirador <a class="header-anchor" href="#a-rotina-do-atirador" aria-label="Permalink to &quot;A rotina do atirador&quot;">​</a></h3><ol><li>Identifique a bola alvo, escolha o ângulo</li><li>Visualize o impacto e o resultado.</li><li>Entre no círculo com um propósito</li><li>Uma respiração profunda, sinta o peso.</li><li>Fixe o olhar no alvo e execute.</li></ol><h2 id="erros-comuns-a-evitar" tabindex="-1">Erros comuns a evitar <a class="header-anchor" href="#erros-comuns-a-evitar" aria-label="Permalink to &quot;Erros comuns a evitar&quot;">​</a></h2><h3 id="muito-longo" tabindex="-1">Muito longo <a class="header-anchor" href="#muito-longo" aria-label="Permalink to &quot;Muito longo&quot;">​</a></h3><p>Se sua rotina leva mais de 30 segundos, você está pensando demais. Rotinas longas dão mais tempo para a ansiedade se acumular.</p><h3 id="muito-rigido" tabindex="-1">Muito rígido <a class="header-anchor" href="#muito-rigido" aria-label="Permalink to &quot;Muito rígido&quot;">​</a></h3><p>Se qualquer interrupção atrapalhar sua rotina, ela é muito frágil. Inclua flexibilidade — se algo quebrar sua concentração, tenha um mecanismo de reinicialização.</p><h3 id="pulando-sob-pressao" tabindex="-1">Pulando sob pressão <a class="header-anchor" href="#pulando-sob-pressao" aria-label="Permalink to &quot;Pulando sob pressão&quot;">​</a></h3><p>A rotina é mais importante quando a pressão é maior. Se você a abandona em momentos de estresse, perde seus benefícios protetores.</p><h3 id="focando-na-mecanica" tabindex="-1">Focando na mecânica <a class="header-anchor" href="#focando-na-mecanica" aria-label="Permalink to &quot;Focando na mecânica&quot;">​</a></h3><p>Sua rotina deve terminar com foco no resultado, não na técnica. &quot;Acerte o alvo&quot;, não &quot;mantenha o cotovelo reto&quot;.</p><h2 id="praticando-sua-rotina" tabindex="-1">Praticando sua rotina <a class="header-anchor" href="#praticando-sua-rotina" aria-label="Permalink to &quot;Praticando sua rotina&quot;">​</a></h2><h3 id="em-treinamento" tabindex="-1">Em treinamento <a class="header-anchor" href="#em-treinamento" aria-label="Permalink to &quot;Em treinamento&quot;">​</a></h3><ul><li>Use sua rotina completa para cada arremesso, mesmo os casuais.</li><li>Cronometre o tempo para garantir a consistência.</li><li>Pratique lidar com distrações para desenvolver resiliência.</li></ul><h3 id="automatizacao-de-edificios" tabindex="-1">Automatização de Edifícios <a class="header-anchor" href="#automatizacao-de-edificios" aria-label="Permalink to &quot;Automatização de Edifícios&quot;">​</a></h3><p>O objetivo é que sua rotina se torne automática — algo que você faça sem pensar. Isso requer repetição:</p><ul><li>Mais de 100 arremessos com a mesma rotina</li><li>Uso consistente em diferentes situações</li><li>Exposição gradual à pressão, mantendo a rotina.</li></ul><h2 id="adaptando-se-a-competicao" tabindex="-1">Adaptando-se à competição <a class="header-anchor" href="#adaptando-se-a-competicao" aria-label="Permalink to &quot;Adaptando-se à competição&quot;">​</a></h2><p>Em partidas, sua rotina pode precisar de pequenos ajustes:</p><ul><li><strong>Pressão de tempo</strong>: Tenha uma versão resumida pronta.</li><li><strong>Condições meteorológicas</strong>: Ajuste os elementos físicos conforme necessário.</li><li><strong>Momentos de alta pressão</strong>: Diminua um pouco a velocidade, não acelere.</li></ul><h2 id="a-rotina-de-reinicializacao" tabindex="-1">A rotina de reinicialização <a class="header-anchor" href="#a-rotina-de-reinicializacao" aria-label="Permalink to &quot;A rotina de reinicialização&quot;">​</a></h2><p>Igualmente importante é o que você faz depois de um arremesso:</p><ol><li>Aceite o resultado — bom ou ruim, está feito.</li><li><strong>Reinicialização física</strong> — dê um passo para trás, libere a tensão</li><li><strong>Reinicialização mental</strong> — livre-se do arremesso da sua mente</li><li><strong>Prepare-se para o próximo passo</strong> — concentre-se no que está por vir.</li></ol><hr><p>| <em>Relacionado: <a href="/en/education/mental-strength/pre-shot-routine">Guia de Rotina Pré-Arremesso</a> | <a href="/en/education/mental-strength/handling-pressure">Lidando com a Pressão</a> | <a href="/en/education/mindfulness/techniques">Técnicas de Mindfulness</a></em> |</p>',54)])])}]]);export{s as __pageData,r as default};
